function createBatcher(flushCallback) {
  let batch = [];
  let isScheduled = false;

  return function add(item) {
    batch.push(item);

    if (!isScheduled) {
      isScheduled = true;
      queueMicrotask(() => {
        const itemsToFlush = [...batch];
        batch = [];
        isScheduled = false;
        flushCallback(itemsToFlush);
      });
    }
  };
}
